import * as arc from "open-arc";

export type ConvertFn = (digits: number[], inputBase: number, outputBase: number) => number[];

export const convertSpec = arc.defineRegion<ConvertFn>({
  "id": "allYourBase.convert",
  "intent": "Exercise \"all-your-base\": implement `convert`.\n\nConvert a sequence of digits in one base, representing a number, into a sequence of digits in another base, representing the same number.\n\n~~~~exercism/note\nTry to implement the conversion yourself.\nDo not use something else to perform the conversion for you.\n~~~~\n\n## About [Positional Notation][positional-notation]\n\nIn positional notation, a number in base **b** can be understood as a linear combination of powers of **b**.\n\nThe number 42, _in base 10_, means:\n\n`(4 × 10¹) + (2 × 10⁰)`\n\nThe number 101010, _in base 2_, means:\n\n`(1 × 2⁵) + (0 × 2⁴) + (1 × 2³) + (0 × 2²) + (1 × 2¹) + (0 × 2⁰)`\n\nThe number 1120, _in base 3_, means:\n\n`(1 × 3³) + (1 × 3²) + (2 × 3¹) + (0 × 3⁰)`\n\n_Yes. Those three numbers above are exactly the same. Congratulations!_\n\n[positional-notation]: https://en.wikipedia.org/wiki/Positional_notation",
  "examples": [
    {
      "name": "Converter > single bit one to decimal",
      "args": [
        [
          1
        ],
        2,
        10
      ],
      "expected": [
        1
      ]
    },
    {
      "name": "Converter > binary to single decimal",
      "args": [
        [
          1,
          0,
          1
        ],
        2,
        10
      ],
      "expected": [
        5
      ]
    },
    {
      "name": "Converter > single decimal to binary",
      "args": [
        [
          5
        ],
        10,
        2
      ],
      "expected": [
        1,
        0,
        1
      ]
    }
  ]
});

// @openarc:begin allYourBase.convert
export const convert: ConvertFn = (digits, inputBase, outputBase) => {
  if (inputBase <= 1 || outputBase <= 1) throw new Error('Wrong input base');
  if (outputBase <= 1) throw new Error('Wrong output base');
  let value = 0;
  for (const digit of digits) {
    if (digit < 0 || digit >= inputBase) throw new Error('Wrong digit');
    value = value * inputBase + digit;
  }
  const result: number[] = [];
  while (value > 0) {
    result.unshift(value % outputBase);
    value = Math.floor(value / outputBase);
  }
  return result;
};
// @openarc:end allYourBase.convert

import * as arc from "open-arc";

export type FindFn = (haystack: number[], needle: number) => number;

export const findSpec = arc.defineRegion<FindFn>({
  "id": "binarySearch.find",
  "intent": "Exercise \"binary-search\": implement `find`.\n\nYour task is to implement a binary search algorithm.\n\nA binary search algorithm finds an item in a list by repeatedly splitting it in half, only keeping the half which contains the item we're looking for.\nIt allows us to quickly narrow down the possible locations of our item until we find it, or until we've eliminated all possible locations.\n\n~~~~exercism/caution\nBinary search only works when a list has been sorted.\n~~~~\n\nThe algorithm looks like this:\n\n- Find the middle element of a _sorted_ list and compare it with the item we're looking for.\n- If the middle element is our item, then we're done!\n- If the middle element is greater than our item, we can eliminate that element and all the elements **after** it.\n- If the middle element is less than our item, we can eliminate that element and all the elements **before** it.\n- If every element of the list has been eliminated then the item is not in the list.\n- Otherwise, repeat the process on the part of the list that has not been eliminated.\n\nHere's an example:\n\nLet's say we're looking for the number 23 in the following sorted list: `[4, 8, 12, 16, 23, 28, 32]`.\n\n- We start by comparing 23 with the middle element, 16.\n- Since 23 is greater than 16, we can eliminate the left half of the list, leaving us with `[23, 28, 32]`.\n- We then compare 23 with the new middle element, 28.\n- Since 23 is less than 28, we can eliminate the right half of the list: `[23]`.\n- We've found our item.",
  "examples": [
    {
      "name": "Binary Search > finds a value in an array with one element",
      "args": [
        [
          6
        ],
        6
      ],
      "expected": 0
    },
    {
      "name": "Binary Search > finds a value in the middle of an array",
      "args": [
        [
          1,
          3,
          4,
          6,
          8,
          9,
          11
        ],
        6
      ],
      "expected": 3
    },
    {
      "name": "Binary Search > finds a value at the beginning of an array",
      "args": [
        [
          1,
          3,
          4,
          6,
          8,
          9,
          11
        ],
        1
      ],
      "expected": 0
    }
  ]
});

// @openarc:begin binarySearch.find
export const find: FindFn = (haystack, needle) => {
  let left = 0;
  let right = haystack.length - 1;
  while (left <= right) {
      const mid = Math.floor((left + right) / 2);
      if (haystack[mid] === needle) {
        return mid;
      } else if (haystack[mid] < needle) {
        left = mid + 1;
      } else {
        right = mid - 1;
      }
    }
  return -1;
};
// @openarc:end binarySearch.find

import * as arc from "open-arc";

export type MakeDiamondFn = (character: string) => string;

export const makeDiamondSpec = arc.defineRegion<MakeDiamondFn>({
  "id": "diamond.makeDiamond",
  "intent": "Exercise "diamond": implement `makeDiamond`.

The diamond kata takes as its input a letter, and outputs it in a diamond shape.
Given a letter, it prints a diamond starting with 'A', with the supplied letter at the widest point.

## Requirements

- The first row contains one 'A'.
- The last row contains one 'A'.
- All rows, except the first and last, have exactly two identical letters.
- All rows have as many trailing spaces as leading spaces. (This might be 0).
- The diamond is horizontally symmetric.
- The diamond is vertically symmetric.
- The diamond has a square shape (width equals height).
- The letters form a diamond shape.
- The top half has the letters in ascending order.
- The bottom half has the letters in descending order.
- The four corners (containing the spaces) are triangles.

## Examples

In the following examples, spaces are indicated by `·` characters.

Diamond for letter 'A':

```text
A
```

Diamond for letter 'C':

```text
··A··
·B·B·
C···C
·B·B·
··A··
```

Diamond for letter 'E':

```text
····A····
···B·B···
··C···C··
·D·····D·
E·······E
·D·····D·
··C···C··
···B·B···
····A····
```",
  "examples": [
    {
      "name": "Make diamond function > test letter A",
      "args": [
        "A"
      ],
      "expected": "A
"
    }
  ]
});

// @openarc:begin diamond.makeDiamond
export const makeDiamond: MakeDiamondFn = (character) => {
  const code = character.charCodeAt(0);
  const start = 'A'.charCodeAt(0);
  const diff = code - start;
  const lines: string[] = [];
  for (let i = 0; i <= diff; i++) {
      const char = String.fromCharCode(start + i);
      const spaces = ' '.repeat(diff - i);
      if (i === 0) {
        lines.push(spaces + char + spaces);
      } else {
        const innerSpaces = ' '.repeat(2 * i - 1);
        lines.push(spaces + char + innerSpaces + char + spaces);
      }
    }
  for (let i = diff - 1; i >= 0; i--) {
      const char = String.fromCharCode(start + i);
      const spaces = ' '.repeat(diff - i);
      if (i === 0) {
        lines.push(spaces + char + spaces);
      } else {
        const innerSpaces = ' '.repeat(2 * i - 1);
        lines.push(spaces + char + innerSpaces + char + spaces);
      }
    }
  return lines.join('
') + '
';
};
// @openarc:end diamond.makeDiamond

import * as arc from "open-arc";

export interface Nested extends Array<number | null | undefined | Nested> {}

export type FlattenFn = (input: Nested) => number[];

export const flattenSpec = arc.defineRegion<FlattenFn>({
  "id": "flattenArray.flatten",
  "intent": "Exercise \"flatten-array\": implement `flatten`.\n\nTake a nested array of any depth and return a fully flattened array.\n\nNote that some language tracks may include null-like values in the input array, and the way these values are represented varies by track.\nSuch values should be excluded from the flattened array.\n\nAdditionally, the input may be of a different data type and contain different types, depending on the track.\n\nCheck the test suite for details.\n\n## Example\n\ninput: `[1, [2, 6, null], [[null, [4]], 5]]`\n\noutput: `[1, 2, 6, 4, 5]`\n\nComments in the stub file:\n/* Parameters go here */",
  "examples": [
    {
      "name": "Flatten Array > no nesting",
      "args": [
        [
          0,
          1,
          2
        ]
      ],
      "expected": [
        0,
        1,
        2
      ]
    },
    {
      "name": "Flatten Array > flattens array with just integers present",
      "args": [
        [
          1,
          [
            2,
            3,
            4,
            5,
            6,
            7
          ],
          8
        ]
      ],
      "expected": [
        1,
        2,
        3,
        4,
        5,
        6,
        7,
        8
      ]
    },
    {
      "name": "Flatten Array > 5 level nesting",
      "args": [
        [
          0,
          2,
          [
            [
              2,
              3
            ],
            8,
            100,
            4,
            [
              [
                [
                  50
                ]
              ]
            ]
          ],
          -2
        ]
      ],
      "expected": [
        0,
        2,
        2,
        3,
        8,
        100,
        4,
        50,
        -2
      ]
    }
  ]
});

// @openarc:begin flattenArray.flatten
export const flatten: FlattenFn = (input) => {
  const result: number[] = [];
  for (const item of input) {
    if (item === null || item === undefined) {
      continue;
    }
    if (Array.isArray(item)) {
      result.push(...flatten(item));
    } else {
      result.push(item);
    }
  }
  return result;
};
// @openarc:end flattenArray.flatten

import * as arc from "open-arc";

export type IsPairedFn = (input: string) => boolean;

export const isPairedSpec = arc.defineRegion<IsPairedFn>({
  "id": "matchingBrackets.isPaired",
  "intent": "Exercise \"matching-brackets\": implement `isPaired`.\n\nGiven a string containing brackets `[]`, braces `{}`, parentheses `()`, or any combination thereof, verify that any and all pairs are matched and nested correctly.\nAny other characters should be ignored.\nFor example, `\"{what is (42)}?\"` is balanced and `\"[text}\"` is not.",
  "examples": [
    {
      "name": "Matching Brackets > paired square brackets",
      "args": [
        "[]"
      ],
      "expected": true
    },
    {
      "name": "Matching Brackets > empty string",
      "args": [
        ""
      ],
      "expected": true
    },
    {
      "name": "Matching Brackets > unpaired brackets",
      "args": [
        "[["
      ],
      "expected": false
    }
  ]
});

// @openarc:begin matchingBrackets.isPaired
export const isPaired: IsPairedFn = (input) => {
  const stack: string[] = [];
  const pairs: { [key: string]: string } = { ")": "(", "]": "[", "}": "{" };
  for (const char of input) {
    if (pairs[char as keyof typeof pairs]) {
      if (stack.pop() !== pairs[char as keyof typeof pairs]) return false;
    } else if ('([{'.includes(char)) {
      stack.push(char);
    }
  } return stack.length === 0;
};
// @openarc:end matchingBrackets.isPaired

import * as arc from "open-arc";

export type AnnotateFn = (field: string[]) => string[];

export const annotateSpec = arc.defineRegion<AnnotateFn>({
  "id": "minesweeper.annotate",
  "intent": "Exercise \"minesweeper\": implement `annotate`.\n\nYour task is to add the mine counts to empty squares in a completed Minesweeper board.\nThe board itself is a rectangle composed of squares that are either empty (`' '`) or a mine (`'*'`).\n\nFor each empty square, count the number of mines adjacent to it (horizontally, vertically, diagonally).\nIf the empty square has no adjacent mines, leave it empty.\nOtherwise replace it with the adjacent mines count.\n\nFor example, you may receive a 5 x 4 board like this (empty spaces are represented here with the '·' character for display on screen):\n\n```text\n·*·*·\n··*··\n··*··\n·····\n```\n\nWhich your code should transform into this:\n\n```text\n1*3*1\n13*31\n·2*2·\n·111·\n```",
  "examples": [
    {
      "name": "Minesweeper annotate > handles no rows",
      "args": [
        []
      ],
      "expected": []
    },
    {
      "name": "Minesweeper annotate > handles no columns",
      "args": [
        [
          ""
        ]
      ],
      "expected": [
        ""
      ]
    },
    {
      "name": "Minesweeper annotate > handles no mines",
      "args": [
        [
          "   ",
          "   ",
          "   "
        ]
      ],
      "expected": [
        "   ",
        "   ",
        "   "
      ]
    }
  ]
});

// @openarc:begin minesweeper.annotate
export const annotate: AnnotateFn = (field) => {
  const rows = field.length;
  if (rows === 0) return [];
  const cols = field[0].length;
  const result = [];
  for (let r = 0; r < rows; r++) {
    const newRow = [];
    for (let c = 0; c < cols; c++) {
      if (field[r][c] === '*') {
        newRow.push('*');
      } else {
        let count = 0;
        for (let dr = -1; dr <= 1; dr++) {
          for (let dc = -1; dc <= 1; dc++) {
            if (dr === 0 && dc === 0) continue;
            const nr = r + dr;
            const nc = c + dc;
            if (nr >= 0 && nr < rows && nc >= 0 && nc < cols && field[nr][nc] === '*') {
              count++;
            }
          }
        }
        newRow.push(count === 0 ? ' ' : String(count));
      }
    }
    result.push(newRow.join(''));
  }
  return result;
};
// @openarc:end minesweeper.annotate

