// @openarc:begin diamond.makeDiamond
export const makeDiamond: MakeDiamondFn = (character) => {
  const code = character.charCodeAt(0) - 'A'.charCodeAt(0);
  const lines: string[] = [];
  for (let i = 0; i <= code; i++) {
      const letter = String.fromCharCode('A'.charCodeAt(0) + i);
      const spaces = ' '.repeat(code - i);
      const row = spaces + letter + (i > 0 ? ' ' + letter : '') + spaces;
      lines.push(row);
    }
  for (let i = code - 1; i >= 0; i--) {
      lines.push(lines[i]);
    }
  return lines.join('\n') + '\n';
};
