// @openarc:begin pigLatin.translate
export const translate: TranslateFn = (phrase) => {
  const vowels = new Set(['a', 'e', 'i', 'o', 'u']);
  const words = phrase.toLowerCase().split(' ');
  const result: string[] = [];
  for (const word of words) {
      if (word.length === 0) {
        result.push(word);
        continue;
      }

      const firstChar = word[0];
      const secondChar = word[1];

      // Rule 1: Starts with vowel, "xr", or "yt"
      if (vowels.has(firstChar) || (secondChar && word.slice(0, 2) === 'xr') || (secondChar && word.slice(0, 2) === 'yt')) {
        result.push(word + 'ay');
        continue;
      }

      // Find the split point for consonants
      let i = 0;
      while (i < word.length) {
        const char = word[i];
        const nextChar = word[i + 1];

        // Rule 3: Handle "qu"
        if (char === 'q' && nextChar === 'u') {
          i += 2;
          break;
        }

        // Rule 4: Handle "y" as a vowel if preceded by consonants
        if (char === 'y' && i > 0) {
          i++;
          break;
        }

        // If current char is a vowel, stop here
        if (vowels.has(char)) {
          break;
        }

        // Consonant
        i++;
      }

      // If we reached the end without finding a vowel (e.g., "rhythm" -> 'y' handled above, but "rhythm" has 'y' at index 2)
      // Actually, the loop breaks on vowel or 'qu' or 'y' (if preceded).
      // If the loop finishes and i == word.length, it means no vowel was found (e.g. "rhythm" -> 'y' is at index 2, so it breaks there).
      // Wait, "rhythm": r(0), h(1), y(2). i=0, char='r' (cons), i=1, char='h' (cons), i=2, char='y'. Since i>0, 'y' is treated as vowel. Break.
      // So i is the index of the first vowel (or the 'y' acting as one).
      // If i == word.length, it means the whole word is consonants (e.g. "rhythm" logic above handles 'y', but what about "bby"? No, 'y' is vowel if preceded).
      // What if word is "bby"? b(0), b(1), y(2). i=0->b, i=1->b, i=2->y (break). Correct.
      // What if word is "b"? i=0->b (cons), i=1 (loop ends). i=1.
      // So the prefix is word.slice(0, i). The suffix is word.slice(i).

      const prefix = word.slice(0, i);
      const suffix = word.slice(i);

      // If the word was all consonants and no vowel found (e.g. "b"), i will be word.length.
      // In that case, we move the whole word to the end (which is empty) and add ay.
      // But wait, "b" -> "bay"? Yes.
      // "rhythm" -> "ythmrhay". prefix="rhm", suffix="yth".
      // "my" -> "ymay". prefix="m", suffix="y".
      // "quick" -> "ickquay". prefix="q", suffix="uick"? No.
      // "quick": q(0), u(1). i=0. char='q'. next='u'. Rule 3 triggers. i becomes 2. prefix="qu", suffix="ick".
      // "square": s(0), q(1), u(2). i=0. char='s'. next='q'. Not 'qu'. i=1. char='q'. next='u'. Rule 3 triggers. i becomes 3. prefix="squ", suffix="are".
      // "chair": c(0), h(1), a(2). i=0->c, i=1->h, i=2->a (vowel). Break. i=2. prefix="ch", suffix="air".

      result.push(suffix + prefix + 'ay');
    }
  return result.join(' ');
};
// @openarc:end pigLatin.translate

