export type CountFn = (rows: string[]) => number;

export const countSpec = arc.defineRegion<CountFn>({
  "id": "rectangles.count",
  "intent": [
    "Exercise \"rectangles\": implement `count`.",
    "Count the rectangles in an ASCII diagram like the one below.",
    "```text +--+ ++  | +-++--+ |  |  | +--+--+ ```",
    "The above diagram contains these 6 rectangles:",
    "```text",
    "+-----+ |     | +-----+ ```",
    "```text +--+ |  | |  | |  | +--+ ```",
    "```text +--+ |  | +--+",
    "```",
    "```text",
    "+--+ |  | +--+ ```",
    "```text",
    "+--+ |  | +--+ ```",
    "```text",
    "++ ++",
    "```",
    "You may assume that the input is always a proper rectangle (i.e. the length of every line equals the length of the first line)."
  ],
  "examples": [
    {
      "name": "Rectangles > no rows",
      "args": [
        []
      ],
      "expected": 0
    },
    {
      "name": "Rectangles > no columns",
      "args": [
        [
          ""
        ]
      ],
      "expected": 0
    },
    {
      "name": "Rectangles > no rectangles",
      "args": [
        [
          " "
        ]
      ],
      "expected": 0
    }
  ]
});

// @openarc:begin rectangles.count
export const count: CountFn = (rows) => {
  const n = rows.length;
  if (n === 0) return 0;
  const m = rows[0].length;
  if (m === 0) return 0;
  const top = rows[0];
  const bottom = rows[n - 1];
  const hasTop = top.includes('+');
  const hasBottom = bottom.includes('+');
  if (!hasTop || !hasBottom) return 0;
  const topIndices = new Set(top.split('').map((c, i) => c === '+' ? i : -1));
  const bottomIndices = new Set(bottom.split('').map((c, i) => c === '+' ? i : -1));
  const commonCols = [];
  for (let i = 0; i < m; i++) {
      if (topIndices.has(i) && bottomIndices.has(i)) {
        commonCols.push(i);
      }
    }
  if (commonCols.length < 2) return 0;
  const colPairs: [number, number][] = [];
  for (let i = 0; i < commonCols.length; i++) {
      for (let j = i + 1; j < commonCols.length; j++) {
        colPairs.push([commonCols[i], commonCols[j]]);
      }
    }
  let count = 0;
  for (const [c1, c2] of colPairs) {
      let valid = true;
      for (let r = 1; r < n - 1; r++) {
        const row = rows[r];
        if (row[c1] !== '|' && row[c1] !== '+') {
          valid = false;
          break;
        }
        if (row[c2] !== '|' && row[c2] !== '+') {
          valid = false;
          break;
        }
      }
      if (valid) {
        count++;
      }
    }
  return count;
};
// @openarc:end rectangles.count

