// @openarc:begin variableLengthQuantity.encode
export const encode: EncodeFn = (numbers) => {
  const result: number[] = [];
    for (const num of numbers) {
      let value = num;
      let byteCount = 0;
      while (true) {
        const byte = (value & 0x7F) | (byteCount > 0 ? 0x80 : 0);
        result.push(byte);
        value >>>= 7;
        if (value === 0) break;
        byteCount++;
      }
    }
    return result;
};
// @openarc:end variableLengthQuantity.encode

