// @openarc:begin minesweeper.annotate
export const annotate: AnnotateFn = (field) => {
  const rows = field.length;
  if (rows === 0) return [];
  const cols = field[0].length;
  const result = [];
  for (let r = 0; r < rows; r++) {
    const newRow = [];
    for (let c = 0; c < cols; c++) {
      if (field[r][c] === '*') {
        newRow.push('*');
      } else {
        let count = 0;
        for (let dr = -1; dr <= 1; dr++) {
          for (let dc = -1; dc <= 1; dc++) {
            if (dr === 0 && dc === 0) continue;
            const nr = r + dr;
            const nc = c + dc;
            if (nr >= 0 && nr < rows && nc >= 0 && nc < cols && field[nr][nc] === '*') {
              count++;
            }
          }
        }
        newRow.push(count === 0 ? ' ' : String(count));
      }
    }
    result.push(newRow.join(''));
  }
  return result;
};
// @openarc:end minesweeper.annotate

