import * as arc from "open-arc";

export type CleanFn = (input: string) => string;

export const cleanSpec = arc.defineRegion<CleanFn>({
  "id": "phoneNumber.clean",
  "intent": "Exercise \"phone-number\": implement `clean`.\n\nClean up phone numbers so that they can be sent SMS messages.\n\nThe **North American Numbering Plan (NANP)** is a telephone numbering system used by many countries in North America like the United States, Canada or Bermuda.\nAll NANP-countries share the same international country code: `1`.\n\nNANP numbers are ten-digit numbers consisting of a three-digit Numbering Plan Area code, commonly known as _area code_, followed by a seven-digit local number.\nThe first three digits of the local number represent the _exchange code_, followed by the unique four-digit number which is the _subscriber number_.\n\nThe format is usually represented as\n\n```text\nNXX NXX-XXXX\n```\n\nwhere `N` is any digit from 2 through 9 and `X` is any digit from 0 through 9.\n\nSometimes they also have the country code (represented as `1` or `+1`) prefixed.\n\nYour task is to clean up differently formatted telephone numbers by removing punctuation and the country code if present.\n\nFor example, the inputs\n\n- `+1 (613)-995-0253`\n- `613-995-0253`\n- `1 613 995 0253`\n- `613.995.0253`\n\nshould all produce the output\n\n`6139950253`\n\n**Note:** As this exercise only deals with telephone numbers used in NANP-countries, only 1 is considered a valid country code.",
  "examples": [
    {
      "name": "Phone Number > Cleanup user-entered phone numbers > cleans the number",
      "args": [
        "(223) 456-7890"
      ],
      "expected": "2234567890"
    },
    {
      "name": "Phone Number > Cleanup user-entered phone numbers > cleans numbers with dots",
      "args": [
        "223.456.7890"
      ],
      "expected": "2234567890"
    }
  ]
});

// @openarc:begin phoneNumber.clean
export const clean: CleanFn = (input) => {
  const cleaned = input.replace(/[\s\-\(\)\+\.]/g, '');
  if (cleaned.length === 11 && cleaned.startsWith('1')) {
      return cleaned.slice(1);
    }
  if (cleaned.length === 10) {
      return cleaned;
    }
  throw new Error('Invalid phone number');
};
// @openarc:end phoneNumber.clean

import * as arc from "open-arc";

export type TranslateFn = (phrase: string) => string;

export const translateSpec = arc.defineRegion<TranslateFn>({
  "id": "pigLatin.translate",
  "intent": "Exercise \"pig-latin\": implement `translate`.\n\nYour task is to translate text from English to Pig Latin.\nThe translation is defined using four rules, which look at the pattern of vowels and consonants at the beginning of a word.\nThese rules look at each word's use of vowels and consonants:\n\n- vowels: the letters `a`, `e`, `i`, `o`, and `u`\n- consonants: the other 21 letters of the English alphabet\n\n## Rule 1\n\nIf a word begins with a vowel, or starts with `\"xr\"` or `\"yt\"`, add an `\"ay\"` sound to the end of the word.\n\nFor example:\n\n- `\"apple\"` -> `\"appleay\"` (starts with vowel)\n- `\"xray\"` -> `\"xrayay\"` (starts with `\"xr\"`)\n- `\"yttria\"` -> `\"yttriaay\"` (starts with `\"yt\"`)\n\n## Rule 2\n\nIf a word begins with one or more consonants, first move those consonants to the end of the word and then add an `\"ay\"` sound to the end of the word.\n\nFor example:\n\n- `\"pig\"` -> `\"igp\"` -> `\"igpay\"` (starts with single consonant)\n- `\"chair\"` -> `\"airch\"` -> `\"airchay\"` (starts with multiple consonants)\n- `\"thrush\"` -> `\"ushthr\"` -> `\"ushthray\"` (starts with multiple consonants)\n\n## Rule 3\n\nIf a word starts with zero or more consonants followed by `\"qu\"`, first move those consonants (if any) and the `\"qu\"` part to the end of the word, and then add an `\"ay\"` sound to the end of the word.\n\nFor example:\n\n- `\"quick\"` -> `\"ickqu\"` -> `\"ickquay\"` (starts with `\"qu\"`, no preceding consonants)\n- `\"square\"` -> `\"aresqu\"` -> `\"aresquay\"` (starts with one consonant followed by `\"qu`\")\n\n## Rule 4\n\nIf a word starts with one or more consonants followed by `\"y\"`, first move the consonants preceding the `\"y\"`to the end of the word, and then add an `\"ay\"` sound to the end of the word.\n\nSome examples:\n\n- `\"my\"` -> `\"ym\"` -> `\"ymay\"` (starts with single consonant followed by `\"y\"`)\n- `\"rhythm\"` -> `\"ythmrh\"` -> `\"ythmrhay\"` (starts with multiple consonants followed by `\"y\"`)",
  "examples": [
    {
      "name": "ay is added to words that start with vowels > word beginning with a",
      "args": [
        "apple"
      ],
      "expected": "appleay"
    },
    {
      "name": "ay is added to words that start with vowels > word beginning with e",
      "args": [
        "ear"
      ],
      "expected": "earay"
    },
    {
      "name": "ay is added to words that start with vowels > word beginning with i",
      "args": [
        "igloo"
      ],
      "expected": "iglooay"
    }
  ]
});

// @openarc:begin pigLatin.translate
export const translate: TranslateFn = (phrase) => {
  return phrase.split(' ').map(word => {
      const vowels = 'aeiou';
      const isVowel = (char: string) => vowels.includes(char);

      // Rule 1: Starts with vowel, 'xr', or 'yt'
      if (word.startsWith('xr') || word.startsWith('yt') || isVowel(word[0])) {
        return word + 'ay';
      }

      // Rule 3: Starts with 'qu' (no preceding consonants)
      if (word.startsWith('qu')) {
        return word.slice(2) + word.slice(0, 2) + 'ay';
      }

      // Rule 4: Starts with consonants followed by 'y' (y acts as vowel if not first char)
      // Find index of 'y' if it exists and is not at index 0
      let yIndex = word.indexOf('y');
      if (yIndex !== -1 && yIndex > 0) {
        // Check if there are consonants before 'y'
        if (word[0] !== 'y') {
          return word.slice(yIndex) + word.slice(0, yIndex) + 'ay';
        }
      }

      // Rule 2: General case for consonants
      let i = 0;
      while (i < word.length && !isVowel(word[i])) {
        i++;
      }

      return word.slice(i) + word.slice(0, i) + 'ay';
    }).join(' ');
};
// @openarc:end pigLatin.translate

import * as arc from "open-arc";

export type CountFn = (rows: string[]) => number;

export const countSpec = arc.defineRegion<CountFn>({
  "id": "rectangles.count",
  "intent": "Exercise \"rectangles\": implement `count`.\n\nCount the rectangles in an ASCII diagram like the one below.\n\n```text\n   +--+\n  ++  |\n+-++--+\n|  |  |\n+--+--+\n```\n\nThe above diagram contains these 6 rectangles:\n\n```text\n\n+-----+\n|     |\n+-----+\n```\n\n```text\n   +--+\n   |  |\n   |  |\n   |  |\n   +--+\n```\n\n```text\n   +--+\n   |  |\n   +--+\n\n```\n\n```text\n\n   +--+\n   |  |\n   +--+\n```\n\n```text\n\n+--+\n|  |\n+--+\n```\n\n```text\n\n  ++\n  ++\n\n```\n\nYou may assume that the input is always a proper rectangle (i.e. the length of every line equals the length of the first line).",
  "examples": [
    {
      "name": "Rectangles > no rows",
      "args": [
        []
      ],
      "expected": 0
    },
    {
      "name": "Rectangles > no columns",
      "args": [
        [
          ""
        ]
      ],
      "expected": 0
    },
    {
      "name": "Rectangles > no rectangles",
      "args": [
        [
          " "
        ]
      ],
      "expected": 0
    }
  ]
});

// @openarc:begin rectangles.count
export const count: CountFn = (rows) => {
  const n = rows.length;
  if (n === 0) return 0;
  const m = rows[0].length;
  if (m === 0) return 0;
  const grid = rows.map(row => row.split(''));
  let total = 0;
  for (let r1 = 0; r1 < n; r1++) {
      for (let r2 = r1 + 1; r2 < n; r2++) {
        for (let c1 = 0; c1 < m; c1++) {
          for (let c2 = c1 + 1; c2 < m; c2++) {
            if (grid[r1][c1] === '+' && grid[r1][c2] === '+' &&
                grid[r2][c1] === '+' && grid[r2][c2] === '+') {
              let valid = true;
              for (let r = r1 + 1; r < r2; r++) {
                if (grid[r][c1] !== '|' || grid[r][c2] !== '|') {
                  valid = false;
                  break;
                }
              }
              if (valid) {
                for (let c = c1 + 1; c < c2; c++) {
                  if (grid[r1][c] !== '-' || grid[r2][c] !== '-') {
                    valid = false;
                    break;
                  }
                }
              }
              if (valid) total++;
            }
          }
        }
      }
    }
  return total;
};
// @openarc:end rectangles.count

