export const find: FindFn = (haystack, needle) => {
  let left = 0;
  let right = haystack.length - 1;
  while (left <= right) {
      const mid = left + Math.floor((right - left) / 2);
      const midValue = haystack[mid];

      if (midValue === needle) {
        return mid;
      } else if (midValue < needle) {
        left = mid + 1;
      } else {
        right = mid - 1;
      }
    }
  return -1;
};
