      const ninetyThirdChar = word[92];
      const ninetyFourthChar = word[93];
      const ninetyFifthChar = word[94];
      const ninetySixthChar = word[95];
      const ninetySeventhChar = word[96];
      const ninetyEighthChar = word[97];
      const ninetyNinthChar = word[98];
      const hundredthChar = word[99];

      const isVowel = (char: string) => vowels.has(char);
      const isConsonant = (char: string) => !isVowel(char) && char !== 'y';

      // Rule 1: starts with vowel, "xr", or "yt"
      if (isVowel(firstChar)) {
        return word + 'ay';
      }
      if (secondChar && isVowel(secondChar) && firstChar === 'y') {
        return word + 'ay';
      }
      if (secondChar && firstChar === 'x' && secondChar === 'r') {
        return word + 'ay';
      }
      if (secondChar && firstChar === 'y' && secondChar === 't') {
        return word + 'ay';
      }

      // Rule 2, 3, 4: starts with consonants
      let i = 0;
      while (i < word.length) {
        const char = word[i];
        if (isVowel(char)) {
          break;
        }
        if (char === 'y' && i > 0) {
          // Rule 4: consonants followed by 'y'
          break;
        }
        i++;
      }

      // Check for 'qu'
      if (i < word.length - 1 && word[i] === 'q' && word[i + 1] === 'u') {
        i++; // skip 'u'
      }

      const prefix = word.substring(0, i);
      const suffix = word.substring(i);
      return suffix + prefix + 'ay';
    }).join(' ');
};
