export const ofSizeSpec = arc.defineRegion<OfSizeFn>({
  "id": "spiralMatrix.ofSize",
  "intent": [
    "Exercise \"spiral-matrix\": implement `ofSize`.",
    "Your task is to return a square matrix of a given size.",
    "The matrix should be filled with natural numbers, starting from 1 in the top-left corner, increasing in an inward, clockwise spiral order, like these examples:",
    "## Examples",
    "### Spiral matrix of size 3",
    "```text 1 2 3 8 9 4 7 6 5 ```",
    "### Spiral matrix of size 4",
    "```text 1  2  3 4 12 13 14 5 11 16 15 6 10  9  8 7 ```"
  ],
  "examples": [
    {
      "name": "Spiral Matrix > empty spiral",
      "args": [
        0
      ],
      "expected": []
    },
    {
      "name": "Spiral Matrix > trivial spiral",
      "args": [
        1
      ],
      "expected": [
        [
          1
        ]
      ]
    }
  ]
});

// @openarc:begin spiralMatrix.ofSize
export const ofSize: OfSizeFn = (size) => {
  if (size === 0) return [];
  const matrix: number[][] = Array.from({ length: size }, () => Array(size).fill(0));
  let num = 1;
  let top = 0, bottom = size - 1, left = 0, right = size - 1;
  while (top <= bottom && left <= right) {
      // Traverse right
      for (let col = left; col <= right; col++) {
        matrix[top][col] = num++;
      }
      top++;

      // Traverse down
      for (let row = top; row <= bottom; row++) {
        matrix[row][right] = num++;
      }
      right--;

      // Traverse left
      if (top <= bottom) {
        for (let col = right; col >= left; col--) {
          matrix[bottom][col] = num++;
        }
        bottom--;
      }

      // Traverse up
      if (left <= right) {
        for (let row = bottom; row >= top; row--) {
          matrix[row][left] = num++;
        }
        left++;
      }
    }
  return matrix;
};
// @openarc:end spiralMatrix.ofSize

