// @openarc:begin variableLengthQuantity.encode
export const encode: EncodeFn = (numbers) => {
  return numbers.map((n) => {
      const result: number[] = [];
      let value = n;
      while (true) {
        const byte = (value & 0x7F) | (value > 0x7F ? 0x80 : 0);
        result.push(byte);
        value >>>= 7;
        if (value === 0) break;
      }
      return result;
    }).flat();
};
// @openarc:end variableLengthQuantity.encode

