// @openarc:begin flattenArray.flatten
export const flatten: FlattenFn = (input) => {
  const result: number[] = [];
  for (const item of input) {
    if (item === null || item === undefined) {
      continue;
    }
    if (Array.isArray(item)) {
      result.push(...flatten(item));
    } else {
      result.push(item);
    }
  }
  return result;
};
