      lines.push(
        `I know an old lady who swallowed a ${animals[n - 1]}.`,
        reactions[n - 1]
      );
    } else {
      lines.push(`I know an old lady who swallowed a ${animals[n - 1]}.`);
      if (n > 1) {
        lines.push(reactions[n - 1]);
      }

      for (let i = n - 1; i >= 1; i--) {
