// @openarc:begin transpose.transpose
export const transpose: TransposeFn = (rows) => {
  if (rows.length === 0) return [];
  const maxLen = Math.max(...rows.map((r) => r.length));
  const result: string[] = [];
  for (let col = 0; col < maxLen; col++) {
      let row = '';
      for (let rowIdx = 0; rowIdx < rows.length; rowIdx++) {
        if (col < rows[rowIdx].length) {
          row += rows[rowIdx][col];
        } else {
          row += ' ';
        }
      }
      result.push(row);
    }
  return result;
};
// @openarc:end transpose.transpose

