// @openarc:begin variableLengthQuantity.decode
export const decode: DecodeFn = (bytes) => {
  const result: number[] = [];
    let currentNumber = 0;
    let bitsCollected = 0;

    for (const byte of bytes) {
      currentNumber = (currentNumber << 7) | (byte & 0x7F);
      bitsCollected += 7;

      if ((byte & 0x80) === 0) {
        result.push(currentNumber);
        currentNumber = 0;
        bitsCollected = 0;
      }
    }

    return result;
};
