// @openarc:begin wordy.answer
export const answer: AnswerFn = (question) => {
  const match = question.match(/^What is (.+?)\?$/);
    if (!match) throw new Error('Invalid syntax');
    const expression = match[1];

    const tokens = expression.split(/\s+/).filter(t => t);
    if (tokens.length === 0) throw new Error('Invalid syntax');

    let result = parseInt(tokens[0], 10);
    if (isNaN(result)) throw new Error('Invalid syntax');

    for (let i = 1; i < tokens.length; i += 2) {
      const op = tokens[i];
      const num = parseInt(tokens[i + 1], 10);
      if (isNaN(num)) throw new Error('Invalid syntax');

      switch (op) {
        case 'plus':
          result += num;
          break;
        case 'minus':
          result -= num;
          break;
        case 'multiplied':
          result *= num;
          break;
        case 'divided':
          result = Math.floor(result / num);
          break;
        default:
          throw new Error('Invalid syntax');
      }
    }

    return result;
};
// @openarc:end wordy.answer
